  const { field, path } = errorLocation(error);
  const code = businessCode(error, field);
  return {
    field,
    path,
    code,
    message: errorMessage(error, field, code),
    keyword: error.keyword,
    details: safeDetails(error),
    schema_path: error.schemaPath,
  };
}

